import{_ as a,o as t,c as o,a6 as s}from"./chunks/framework.DMOj2-2K.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),i={name:"faq.md"};function r(n,e,d,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Straight answers to the questions people ask most about Cluub 0.1, including what it can&#39;t do yet. Where an answer depends on how the code behaves today, it was checked against the source and by running real projects.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><h3 id="what-is-cluub-in-one-sentence" tabindex="-1">What is Cluub, in one sentence? <a class="header-anchor" href="#what-is-cluub-in-one-sentence" aria-label="Permalink to &quot;What is Cluub, in one sentence?&quot;">​</a></h3><p>A small, structured programming language that <strong>clubs together</strong> the frontend, the backend and AI: you write <code>.clb</code> files, and Cluub builds the web pages, the API server, the AI calls and the tests, with zero dependencies.</p><h3 id="is-cluub-a-library-a-framework-or-a-language" tabindex="-1">Is Cluub a library, a framework or a language? <a class="header-anchor" href="#is-cluub-a-library-a-framework-or-a-language" aria-label="Permalink to &quot;Is Cluub a library, a framework or a language?&quot;">​</a></h3><p><strong>A language with a built-in framework.</strong></p><ul><li>A <strong>library</strong> is code <em>you</em> call (like Lodash or the OpenAI SDK). Cluub is not that: you don&#39;t import it into another program.</li><li>A <strong>framework</strong> calls <em>your</em> code and decides the structure (like Angular or Next.js). Cluub does this: it decides the folder layout and the layers, wires dependencies and runs your pages and routes.</li><li>A <strong>language</strong> has its own syntax and compiler. Cluub has both: <code>.clb</code> files are parsed, checked and compiled to plain JavaScript.</li></ul><p>So it&#39;s closest to Elm or Svelte: a language whose compiler and runtime act as the framework.</p><h3 id="how-do-i-install-it" tabindex="-1">How do I install it? <a class="header-anchor" href="#how-do-i-install-it" aria-label="Permalink to &quot;How do I install it?&quot;">​</a></h3><p>With Node.js 18 or newer, like Vite or Angular:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluub@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Or install the command globally and use <code>cluub new my-app</code>. See <a href="/guide/install">Install &amp; first app</a>.</p><h3 id="why-the-name-cluub" tabindex="-1">Why the name Cluub? <a class="header-anchor" href="#why-the-name-cluub" aria-label="Permalink to &quot;Why the name Cluub?&quot;">​</a></h3><p>Because it <em>clubs</em> frontend, backend and AI into one language. The logo hides the double <strong>u</strong> inside a cat: its happy closed eyes are the <em>uu</em> of cluub. See <a href="/brand">Brand &amp; logo</a>.</p><h3 id="where-is-the-source-code-and-is-it-open-source" tabindex="-1">Where is the source code, and is it open source? <a class="header-anchor" href="#where-is-the-source-code-and-is-it-open-source" aria-label="Permalink to &quot;Where is the source code, and is it open source?&quot;">​</a></h3><p>Cluub is MIT-licensed open source. The code lives at <a href="https://github.com/cluub-lang/cluub" target="_blank" rel="noreferrer">github.com/cluub-lang/cluub</a> and is published to npm as <code>cluub</code> and <code>create-cluub</code>.</p><h2 id="the-language" tabindex="-1">The language <a class="header-anchor" href="#the-language" aria-label="Permalink to &quot;The language&quot;">​</a></h2><h3 id="why-a-new-language-instead-of-typescript-and-react" tabindex="-1">Why a new language instead of TypeScript and React? <a class="header-anchor" href="#why-a-new-language-instead-of-typescript-and-react" aria-label="Permalink to &quot;Why a new language instead of TypeScript and React?&quot;">​</a></h3><p>A web feature in the usual stack spans a framework, a router, a state library, an HTTP server, a validation library, a test runner and an AI SDK, each with its own conventions. Cluub replaces that wiring with one small language whose compiler <strong>enforces</strong> one structure. That gives three things a library can&#39;t guarantee:</p><ul><li>every project has the same folders and the same layer rules (errors E301, E201), so any developer or AI finds anything immediately,</li><li>validation, error display, dependency wiring and awaiting happen automatically,</li><li>the compiler knows the whole app, so it can generate tests and plain-English overviews from it.</li></ul><p>The cost is a smaller ecosystem and a young toolchain. If you need the npm ecosystem, an existing React codebase or fine-grained control over rendering, stay with TypeScript and React. See <a href="/guide/introduction">Why Cluub</a>.</p><h3 id="who-is-cluub-for" tabindex="-1">Who is Cluub for? <a class="header-anchor" href="#who-is-cluub-for" aria-label="Permalink to &quot;Who is Cluub for?&quot;">​</a></h3><p>Small full-stack apps, internal tools, prototypes and AI-backed features, built by mixed teams where product owners, BAs and QAs read the code too. It isn&#39;t aimed yet at large public sites with heavy traffic, complex auth or big data.</p><h3 id="why-does-cluub-use-words-like-is-and-and-instead-of-and" tabindex="-1">Why does Cluub use words like <code>is</code> and <code>and</code> instead of <code>==</code> and <code>&amp;&amp;</code>? <a class="header-anchor" href="#why-does-cluub-use-words-like-is-and-and-instead-of-and" aria-label="Permalink to &quot;Why does Cluub use words like `is` and `and` instead of `==` and `&amp;&amp;`?&quot;">​</a></h3><p>So code reads like a sentence, works with voice dictation and can be reviewed by non-developers. Writing <code>==</code>, <code>!=</code>, <code>&amp;&amp;</code>, <code>||</code> or <code>!</code> is error <strong>E006</strong>, with a hint that names the word to use instead.</p><h3 id="why-is-indentation-an-error-instead-of-a-style-choice" tabindex="-1">Why is indentation an error instead of a style choice? <a class="header-anchor" href="#why-is-indentation-an-error-instead-of-a-style-choice" aria-label="Permalink to &quot;Why is indentation an error instead of a style choice?&quot;">​</a></h3><p>Blocks are defined by indentation, so a misaligned line changes the program&#39;s meaning. Rejecting tabs (E001) and anything other than 2-space steps (E002, E003) makes every file look identical, and the compiler never has to guess.</p><h3 id="why-is-something-that-works-in-other-languages-an-error-here" tabindex="-1">Why is something that works in other languages an error here? <a class="header-anchor" href="#why-is-something-that-works-in-other-languages-an-error-here" aria-label="Permalink to &quot;Why is something that works in other languages an error here?&quot;">​</a></h3><p>Most Cluub errors protect an architectural rule rather than syntax. Every code comes with a hint, and <code>cluub errors CODE</code> explains it:</p><table tabindex="0"><thead><tr><th>Error</th><th>The rule it protects</th></tr></thead><tbody><tr><td>E201</td><td>the UI talks to data only through an api; apis only call services</td></tr><tr><td>E106</td><td>every dependency is declared with <code>uses</code> (so tests can swap it)</td></tr><tr><td>E204 / E205</td><td>AI and secrets never reach the browser</td></tr><tr><td>E301</td><td>everyone can find every file</td></tr><tr><td>E102 / E103</td><td>one naming style everywhere</td></tr><tr><td>E112</td><td>inputs are bound to page state, so the value isn&#39;t lost</td></tr><tr><td>E401</td><td>keys never end up in source control</td></tr><tr><td>E117</td><td>views only show data: no api calls or actions while drawing</td></tr></tbody></table><p>Warnings (W…) and suggestions never block a build. See <a href="/reference/errors">Error codes</a>.</p><h3 id="can-i-write-a-component-with-its-own-state" tabindex="-1">Can I write a component with its own state? <a class="header-anchor" href="#can-i-write-a-component-with-its-own-state" aria-label="Permalink to &quot;Can I write a component with its own state?&quot;">​</a></h3><p>No. Components are stateless by design (<code>takes</code> only, no <code>state</code>, no <code>uses</code>), and pages own the data. A component reports events back through an <code>action</code> property, as in <code>takes onRemove: action</code>. This keeps components reusable and easy to test. See <a href="/guide/frontend">Pages &amp; components</a>.</p><h2 id="ecosystem-and-integration" tabindex="-1">Ecosystem and integration <a class="header-anchor" href="#ecosystem-and-integration" aria-label="Permalink to &quot;Ecosystem and integration&quot;">​</a></h2><h3 id="can-i-use-npm-packages" tabindex="-1">Can I use npm packages? <a class="header-anchor" href="#can-i-use-npm-packages" aria-label="Permalink to &quot;Can I use npm packages?&quot;">​</a></h3><p>No. Cluub has no <code>import</code> statement, and a project has no <code>package.json</code>. The toolchain and the generated code have zero dependencies. To use outside functionality, call it over HTTP with a <a href="/reference/client"><code>client</code></a> from a service, or run it as a separate service your Cluub app calls.</p><h3 id="does-it-support-databases" tabindex="-1">Does it support databases? <a class="header-anchor" href="#does-it-support-databases" aria-label="Permalink to &quot;Does it support databases?&quot;">​</a></h3><p>Not yet. Stores are in memory or saved to a JSON file (<code>saved in &quot;storage/x.json&quot;</code>). File stores keep all records in memory and rewrite the file on every write, which is fine for small apps and prototypes but not for high write volume or several server processes. Postgres and SQLite stores with generated migrations are on the <a href="/reference/roadmap">roadmap</a>. Services only talk to the store interface (<code>all</code>, <code>get</code>, <code>add</code>, ...), so changing the store later shouldn&#39;t touch service code.</p><h3 id="does-it-support-authentication" tabindex="-1">Does it support authentication? <a class="header-anchor" href="#does-it-support-authentication" aria-label="Permalink to &quot;Does it support authentication?&quot;">​</a></h3><p>No. There are no sessions, logins, roles or cookie access in 0.1, so every api route is public. Put authentication in front of the app with a reverse proxy or an SSO gateway. See <a href="/guide/security#no-authentication-sessions-or-roles">Security</a>. Auth (<code>page Admin at &quot;/admin&quot; for role &quot;admin&quot;</code>) is on the roadmap.</p><h3 id="file-uploads-websockets-streaming-ai-replies" tabindex="-1">File uploads, websockets, streaming AI replies? <a class="header-anchor" href="#file-uploads-websockets-streaming-ai-replies" aria-label="Permalink to &quot;File uploads, websockets, streaming AI replies?&quot;">​</a></h3><p>Not supported yet. Request bodies are JSON only, up to 1,000,000 bytes, sent with <code>Content-Type: application/json</code>.</p><h3 id="can-i-call-my-existing-rest-api" tabindex="-1">Can I call my existing REST API? <a class="header-anchor" href="#can-i-call-my-existing-rest-api" aria-label="Permalink to &quot;Can I call my existing REST API?&quot;">​</a></h3><p>Yes, with a <code>client</code> in <code>network/</code>:</p><div class="language-cluub vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cluub</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">client</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Weather</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.open-meteo.com/v1&quot;</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;User-Agent&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;my-app&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> forecast </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/forecast&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> latitude: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, longitude: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">number</span></span></code></pre></div><p>A service then <code>uses Weather</code> and calls <code>Weather.forecast(52.5, 13.4)</code>. Calls time out after 15 seconds and fail with a clear <code>502</code> message. In tests, client calls return <code>nothing</code> (no network).</p><h3 id="can-i-deploy-the-frontend-and-backend-separately" tabindex="-1">Can I deploy the frontend and backend separately? <a class="header-anchor" href="#can-i-deploy-the-frontend-and-backend-separately" aria-label="Permalink to &quot;Can I deploy the frontend and backend separately?&quot;">​</a></h3><p>Not in 0.1. <code>cluub start</code> (or <code>node dist/start.mjs</code>) serves both from one Node process, and the server doesn&#39;t send CORS headers. Separate static and serverless targets are on the roadmap. See <a href="/guide/deployment">Deployment</a>.</p><h2 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;AI&quot;">​</a></h2><h3 id="does-cluub-provide-an-ai-key-or-charge-for-ai" tabindex="-1">Does Cluub provide an AI key, or charge for AI? <a class="header-anchor" href="#does-cluub-provide-an-ai-key-or-charge-for-ai" aria-label="Permalink to &quot;Does Cluub provide an AI key, or charge for AI?&quot;">​</a></h3><p>No. Cluub is <strong>bring-your-own-key</strong>: it never ships a key, never routes your requests through a Cluub server, and never charges for AI. Calls go directly from your server to the provider using a key that you, or your users, own. Add yours with <code>cluub ai set claude</code> (or <code>openai</code> / <code>gemini</code>), or use a local Ollama model with no key at all. See <a href="/guide/ai-keys">Your own AI keys</a>.</p><h3 id="can-the-users-of-my-app-bring-their-own-ai-keys" tabindex="-1">Can the users of my app bring their own AI keys? <a class="header-anchor" href="#can-the-users-of-my-app-bring-their-own-ai-keys" aria-label="Permalink to &quot;Can the users of my app bring their own AI keys?&quot;">​</a></h3><p>Yes. Set <code>aiKeys &quot;user&quot;</code> in <code>app.clb</code> and put the built-in <code>aikey</code> element on a page. Each user pastes their own key; it stays in their browser and is sent only with their requests, where the server uses it for that request and never stores or logs it. <code>aiKeys &quot;either&quot;</code> uses the user&#39;s key when they added one and yours otherwise. See <a href="/guide/ai-keys#end-user-keys-aikeys-user-and-the-aikey-element">Your own AI keys</a>.</p><h3 id="where-are-my-keys-stored-and-can-they-leak-into-git" tabindex="-1">Where are my keys stored, and can they leak into git? <a class="header-anchor" href="#where-are-my-keys-stored-and-can-they-leak-into-git" aria-label="Permalink to &quot;Where are my keys stored, and can they leak into git?&quot;">​</a></h3><p>On your machine, in the project&#39;s <code>.env</code> file. <code>cluub ai set</code> writes it with permissions only you can read and adds <code>.env</code> to <code>.gitignore</code>. In production, set keys as real environment variables in your hosting provider; they take priority over <code>.env</code>. A key typed directly into a <code>.clb</code> file is compile error E401.</p><h3 id="how-do-ai-keys-stay-safe" tabindex="-1">How do AI keys stay safe? <a class="header-anchor" href="#how-do-ai-keys-stay-safe" aria-label="Permalink to &quot;How do AI keys stay safe?&quot;">​</a></h3><p>On three levels:</p><ol><li><strong>Compile time:</strong> <code>ask ai</code> outside services, apis and clients is error E204, <code>env.X</code> in the UI is E205, and a key-like string in code is E401.</li><li><strong>Build output:</strong> the browser bundle contains no service code, no <code>env</code> reads and no AI calls. The browser can only reach your api routes.</li><li><strong>Runtime:</strong> keys are read from <code>.env</code> or the environment on the server and sent only in request headers to the provider. In production, AI errors reach the browser only as a generic message; details stay in the server log.</li></ol><p><code>cluub make</code> sends your <code>.clb</code> files (not <code>.env</code>) to the AI provider you choose.</p><h3 id="which-ai-providers-work-can-i-use-a-local-model" tabindex="-1">Which AI providers work? Can I use a local model? <a class="header-anchor" href="#which-ai-providers-work-can-i-use-a-local-model" aria-label="Permalink to &quot;Which AI providers work? Can I use a local model?&quot;">​</a></h3><p>Claude (<code>ANTHROPIC_API_KEY</code>), OpenAI (<code>OPENAI_API_KEY</code>), Gemini (<code>GEMINI_API_KEY</code>) and Ollama (local, no key). Set the default with <code>ai &quot;ollama&quot;</code> in <code>app.clb</code>, or per call with <code>using &quot;ollama:llama3.2&quot;</code>. <code>CLUUB_AI</code> in the environment or <code>.env</code> overrides the <code>ai</code> line, so each environment can pick its own provider. All four providers are implemented and tested offline with the fake AI, but live calls haven&#39;t been tested end to end for every provider. See <a href="/guide/ai">AI</a>.</p><h3 id="do-tests-cost-money-or-need-a-network-connection" tabindex="-1">Do tests cost money or need a network connection? <a class="header-anchor" href="#do-tests-cost-money-or-need-a-network-connection" aria-label="Permalink to &quot;Do tests cost money or need a network connection?&quot;">​</a></h3><p>No. Tests use a fake AI: a predictable text reply, a valid sample for <code>as Model</code>, the first option for <code>as one of</code>. They never make network calls. A full template test run takes about 10 ms.</p><h3 id="is-ai-written-code-cluub-make-safe-to-merge" tabindex="-1">Is AI-written code (<code>cluub make</code>) safe to merge? <a class="header-anchor" href="#is-ai-written-code-cluub-make-safe-to-merge" aria-label="Permalink to &quot;Is AI-written code (`cluub make`) safe to merge?&quot;">​</a></h3><p>It&#39;s compiled before anything is written. Files are only written if the whole project compiles, and the AI gets up to three tries to fix compile errors. Compiling proves structure and names, not intent, so review the diff and run <code>cluub test</code> as you would for a human change.</p><h2 id="working-with-cluub" tabindex="-1">Working with Cluub <a class="header-anchor" href="#working-with-cluub" aria-label="Permalink to &quot;Working with Cluub&quot;">​</a></h2><h3 id="how-do-i-debug" tabindex="-1">How do I debug? <a class="header-anchor" href="#how-do-i-debug" aria-label="Permalink to &quot;How do I debug?&quot;">​</a></h3><ul><li><strong>Compile problems:</strong> <code>cluub check</code> or the <code>cluub dev</code> terminal. Each message has a file, a line, a caret and a hint.</li><li><strong>Backend values:</strong> <code>log value</code> in a service prints <code>[log] ...</code> in the server terminal.</li><li><strong>Frontend values:</strong> <code>log value</code> in a page action prints to the browser console.</li><li><strong>Server errors:</strong> the server terminal always prints the full error. <code>cluub dev</code> also shows it in the toast and prints stack lines.</li><li><strong>Generated code:</strong> read <code>dist/server.js</code> and <code>dist/public/_cluub/app.client.js</code>. They&#39;re readable JavaScript. Errors point there, not to <code>.clb</code> lines (source maps are planned).</li><li><strong>CLI failures:</strong> <code>CLUUB_DEBUG=1 cluub build</code> prints the stack trace.</li></ul><p>There is no step debugger integration yet.</p><h3 id="is-there-editor-support" tabindex="-1">Is there editor support? <a class="header-anchor" href="#is-there-editor-support" aria-label="Permalink to &quot;Is there editor support?&quot;">​</a></h3><p>Syntax highlighting through the TextMate grammar in <code>editors/cluub.tmLanguage.json</code>. A language server with inline errors and completion is the first item on the roadmap. Until it lands, keep <code>cluub dev</code> running: it re-checks on every save.</p><h3 id="can-i-eject-to-plain-javascript" tabindex="-1">Can I eject to plain JavaScript? <a class="header-anchor" href="#can-i-eject-to-plain-javascript" aria-label="Permalink to &quot;Can I eject to plain JavaScript?&quot;">​</a></h3><p>There is no eject command, but <code>dist/</code> is already standalone: it contains your compiled app plus a copy of the runtime, and <code>node dist/start.mjs</code> runs it with plain Node.js, without the Cluub toolchain. All of it is readable JavaScript with no dependencies (MIT licensed, about 1,000 lines of runtime). You could keep developing that output by hand, but you&#39;d lose the compiler&#39;s checks, generated tests and <code>explain</code>, and the generated code isn&#39;t designed to be edited.</p><h3 id="how-fast-is-it" tabindex="-1">How fast is it? <a class="header-anchor" href="#how-fast-is-it" aria-label="Permalink to &quot;How fast is it?&quot;">​</a></h3><p>On an Apple M3: the <code>app</code> template compiles in about 0.5 ms, <code>cluub test</code> takes 88 ms including Node startup, and one server handled 8,000–10,000 small api reads per second with an idle memory use of 64 MB. Read <a href="/guide/performance">Performance</a> for the methods and the caveats.</p><h3 id="does-it-work-on-windows" tabindex="-1">Does it work on Windows? <a class="header-anchor" href="#does-it-work-on-windows" aria-label="Permalink to &quot;Does it work on Windows?&quot;">​</a></h3><p>The CLI uses Node&#39;s cross-platform <code>path</code> handling and <code>fs.watch</code> with recursive mode, which Windows supports. We haven&#39;t tested 0.1 on Windows. On Linux, <code>cluub dev</code> needs Node 20 or newer for recursive file watching.</p><h3 id="how-do-i-add-css" tabindex="-1">How do I add CSS? <a class="header-anchor" href="#how-do-i-add-css" aria-label="Permalink to &quot;How do I add CSS?&quot;">​</a></h3><p>Put a <code>theme.css</code> in the project root. It&#39;s linked after the built-in theme, so you can override variables such as <code>--primary</code>, <code>--radius</code> and <code>--font</code>, or define classes and use them with <code>class &quot;my-class&quot;</code>. Images and other files go in <code>assets/</code> and are served from <code>/assets/</code>.</p><h3 id="can-i-have-more-than-one-app-per-server" tabindex="-1">Can I have more than one app per server? <a class="header-anchor" href="#can-i-have-more-than-one-app-per-server" aria-label="Permalink to &quot;Can I have more than one app per server?&quot;">​</a></h3><p>No. One project builds one app with one <code>app</code> declaration (a second one is error E101).</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><h3 id="is-cluub-production-ready" tabindex="-1">Is Cluub production ready? <a class="header-anchor" href="#is-cluub-production-ready" aria-label="Permalink to &quot;Is Cluub production ready?&quot;">​</a></h3><p>No. It&#39;s a <strong>beta (0.1.0-beta.1)</strong>. The compiler, runtime and CLI work end to end, and the templates pass their tests, but:</p><ul><li>there&#39;s no auth, no database and no rate limiting,</li><li>runtime errors point to generated JavaScript,</li><li>type checking is partial (values are checked at runtime boundaries),</li><li>the server has no automatic restart, compression or HTTPS. Run it behind a proxy and a process manager (<a href="/guide/deployment">Deployment</a>).</li></ul><p>Use it for prototypes, internal tools and learning. If you deploy, follow the checklist in <a href="/guide/security#checklist-before-going-live">Security</a>.</p><h3 id="is-it-on-npm" tabindex="-1">Is it on npm? <a class="header-anchor" href="#is-it-on-npm" aria-label="Permalink to &quot;Is it on npm?&quot;">​</a></h3><p>The packages are ready to publish as <strong><code>cluub</code></strong> (the compiler and command) and <strong><code>create-cluub</code></strong> (for <code>npm create cluub@latest</code>). Until they&#39;re published, install from the source folder with <code>npm link</code> (<a href="/guide/install">Install</a>).</p><h3 id="where-is-the-documentation-hosted" tabindex="-1">Where is the documentation hosted? <a class="header-anchor" href="#where-is-the-documentation-hosted" aria-label="Permalink to &quot;Where is the documentation hosted?&quot;">​</a></h3><p>At <strong><a href="https://cluub-lang.github.io/" target="_blank" rel="noreferrer">cluub-lang.github.io</a></strong>, published free by GitHub Pages and rebuilt automatically on every change to the code. The site is plain static files built with VitePress, so you can also host a copy anywhere (see <a href="/contributing#publishing-the-docs-site">Contributing</a>). See <a href="/contributing#publishing-the-docs-site">Contributing</a>.</p><h3 id="how-do-i-report-a-bug-or-contribute" tabindex="-1">How do I report a bug or contribute? <a class="header-anchor" href="#how-do-i-report-a-bug-or-contribute" aria-label="Permalink to &quot;How do I report a bug or contribute?&quot;">​</a></h3><p>See <a href="/contributing">Contributing</a>. The compiler and runtime are dependency-free JavaScript, and <code>node tests/run.js</code> checks templates, examples and every code sample in the docs.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/introduction">Why Cluub</a></li><li><a href="/guide/troubleshooting">Troubleshooting</a></li><li><a href="/glossary">Glossary</a></li><li><a href="/reference/roadmap">Status &amp; roadmap</a></li></ul>',95)])])}const g=a(i,[["render",r]]);export{p as __pageData,g as default};
